-- A28: cobertura opaca de anexo no rascunho de venda; sem chave, URL, nome, tipo, tamanho, conteúdo, download ou visualização.
create or replace function public.subdivision_list_sale_draft_attachment_coverage(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(sale_draft_id uuid,attachment_coverage_state text) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select sd.id,case when ai.id is null then 'no_attachment_intent' when ai.storage_key is null then 'attachment_awaiting_private_upload' else 'attachment_private_upload_recorded' end from public.subdivision_sale_drafts sd left join public.subdivision_buyer_attachment_intents ai on ai.organization_id=sd.organization_id and ai.buyer_client_id=sd.buyer_client_id where sd.organization_id=p_organization_id;end;$$;
revoke all on function public.subdivision_list_sale_draft_attachment_coverage(uuid,uuid,public.operating_module,text) from public,anon,authenticated;
grant execute on function public.subdivision_list_sale_draft_attachment_coverage(uuid,uuid,public.operating_module,text) to service_role;
